<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { BellRing, Bot, Camera, CheckCircle2, Clock3, Eye, KeyRound, MousePointer2, Palette, Quote, RotateCw, Save, Sparkles, Trash2, Type, UserRound } from 'lucide-vue-next'
import AppButton from '../components/ui/AppButton.vue'
import AppCard from '../components/ui/AppCard.vue'
import AppTabs from '../components/ui/AppTabs.vue'
import InlineStatus, { type InlineStatusState } from '../components/ui/InlineStatus.vue'
import AvatarEditor from '../components/profile/AvatarEditor.vue'
import UserAvatar from '../components/profile/UserAvatar.vue'
import { useAuthStore } from '../stores/auth'
import { useContextStore } from '../stores/context'
import { usePreferencesStore } from '../stores/preferences'
import { useLegacyMutationRuntime } from '../features/shared/useLegacyMutationRuntime'
import { saveSettingsMutation } from '../features/settings/settings-mutations'
import { legacyApi } from '../services/legacy-supabase'
import { validateAvatarFile } from '../features/profile/avatar-image.js'

const auth=useAuthStore(),context=useContextStore(),preferences=usePreferencesStore(),createRuntime=useLegacyMutationRuntime(),route=useRoute()
const isLearner=computed(()=>auth.currentUser?.role==='student'||auth.currentUser?.role==='monitor')
const isAdmin=computed(()=>auth.currentUser?.role==='admin')
const isTeacher=computed(()=>auth.currentUser?.role==='teacher')
const isPersonalSettings=computed(()=>isLearner.value||isAdmin.value||(isTeacher.value&&route.query.view==='personal'))
const isMonitor=computed(()=>auth.currentUser?.role==='monitor')
const activeTab=ref('general'),saving=ref(false),status=ref<InlineStatusState>('idle'),statusMessage=ref('')
const personalStatus=ref<InlineStatusState>('idle'),personalMessage=ref(''),passwordBusy=ref(false),currentPassword=ref(''),newPassword=ref('')
const avatarInput=ref<HTMLInputElement|null>(null),avatarEditorFile=ref<File|null>(null)
const tabs=[{id:'general',label:'Chung & đăng ký'},{id:'ai',label:'AI duyệt'},{id:'owl',label:'Cú Thông Thái'}]
const announcement=ref(''),registrationDeadlineTime=ref('20:00'),aiAutoApproveThreshold=ref(90),smartApprovalEnabled=ref(true)
const settings=computed(()=>auth.legacyState?.settings??{})
const memory=computed<Record<string,unknown>>(()=>((auth.legacyState?.aiFeedbackMemoryStats as Record<string,unknown>|undefined)??{}))
const revisionThreshold=computed(()=>Math.round(Number(settings.value.aiRevisionActionThreshold??.85)*100))
const roleLabel=computed(()=>auth.currentUser?.role==='monitor'?'Cán sự lớp':auth.currentUser?.role==='student'?'Học sinh':auth.currentUser?.role==='admin'?'Quản trị viên':'Giáo viên')
const classLabel=computed(()=>context.selectedClass?.code||context.selectedClass?.name||String(settings.value.className??''))
const owlMotionModel=computed({get:()=>preferences.owlMotionEnabled,set:value=>{preferences.owlMotionEnabled=value}})
function hydrate(){announcement.value=String(settings.value.announcement??'');registrationDeadlineTime.value=String(settings.value.registrationDeadlineTime??'20:00');aiAutoApproveThreshold.value=Math.round(Number(settings.value.aiAutoApproveThreshold??.9)*100);smartApprovalEnabled.value=Boolean(settings.value.aiAutomationEnabled??settings.value.smartApprovalEnabled??settings.value.aiReviewEnabled??true)}
watch(settings,hydrate,{immediate:true})
async function save(){if(!context.selectedClassId)return;saving.value=true;status.value='idle';try{await saveSettingsMutation(createRuntime(),context.selectedClassId,{announcement:announcement.value,registrationDeadlineTime:registrationDeadlineTime.value,aiAutomationEnabled:smartApprovalEnabled.value,aiAutoApproveThreshold:aiAutoApproveThreshold.value/100});status.value='success';statusMessage.value=`Đã lưu cài đặt. Deadline tự động: ${registrationDeadlineTime.value}.`}catch(error){status.value='error';statusMessage.value=error instanceof Error?error.message:'Không lưu được cài đặt.'}finally{saving.value=false}}
async function changePassword(){if(!currentPassword.value||newPassword.value.length<8){personalStatus.value='error';personalMessage.value='Mật khẩu mới cần ít nhất 8 ký tự và phải nhập mật khẩu hiện tại.';return}passwordBusy.value=true;personalStatus.value='idle';try{await legacyApi.changeOwnPassword(currentPassword.value,newPassword.value);currentPassword.value='';newPassword.value='';personalStatus.value='success';personalMessage.value='Đã đổi mật khẩu.'}catch(error){personalStatus.value='error';personalMessage.value=error instanceof Error?error.message:'Không đổi được mật khẩu.'}finally{passwordBusy.value=false}}
function chooseAvatar(){avatarInput.value?.click()}
function onAvatarFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0]??null;if(!file)return;const result=validateAvatarFile(file);if(!result.ok){personalStatus.value='error';personalMessage.value=result.message;input.value='';return}personalStatus.value='idle';personalMessage.value='';avatarEditorFile.value=file}
function closeAvatarEditor(){avatarEditorFile.value=null;if(avatarInput.value)avatarInput.value.value=''}
async function saveAvatar(blob:Blob){personalStatus.value='idle';personalMessage.value='';try{await auth.uploadAvatar(blob);personalStatus.value='success';personalMessage.value='Đã cập nhật ảnh đại diện.';closeAvatarEditor()}catch(error){personalStatus.value='error';personalMessage.value=error instanceof Error?error.message:'Không lưu được ảnh đại diện.'}}
async function removeAvatar(){if(!auth.currentUser?.avatarPath)return;if(!window.confirm('Xóa ảnh đại diện và quay lại ảnh chữ viết tắt?'))return;personalStatus.value='idle';personalMessage.value='';try{await auth.deleteAvatar();personalStatus.value='success';personalMessage.value='Đã xóa ảnh đại diện.'}catch(error){personalStatus.value='error';personalMessage.value=error instanceof Error?error.message:'Không xóa được ảnh đại diện.'}}

</script>

<template>
  <div v-if="isPersonalSettings" class="page-stack personal-settings">
    <nav v-if="isTeacher" class="teacher-settings-switch" aria-label="Chế độ cài đặt"><RouterLink :to="{path:'/settings',query:{view:'personal'}}" class="active">Tùy chọn cá nhân</RouterLink><RouterLink to="/settings">Cấu hình ứng dụng</RouterLink></nav>
    <header class="personal-header"><span>TÙY CHỌN CÁ NHÂN</span><h1>Cài đặt của tôi</h1><p>Quản lý ảnh đại diện, giao diện và Cú Thông Thái cho tài khoản này. Các cảnh báo bắt buộc của hệ thống không phụ thuộc việc ẩn Cú.</p></header>
    <InlineStatus :state="personalStatus" :message="personalMessage"/>
    <section class="personal-grid">
      <AppCard padding="lg" class="personal-card avatar-card"><div class="section-title"><Camera/><div><span>ẢNH ĐẠI DIỆN</span><h2>Hình ảnh của tôi</h2></div></div><div class="avatar-settings"><UserAvatar :src="auth.avatarUrl" :name="auth.currentUser?.name" :code="auth.currentUser?.code" size="lg"/><div class="avatar-copy"><b>{{ auth.currentUser?.avatarPath ? 'Ảnh đại diện hiện tại' : 'Đang dùng chữ viết tắt' }}</b><small>JPG, PNG hoặc WEBP · tối đa 5 MB. Ảnh được cắt vuông và lưu 512 × 512 px.</small><input ref="avatarInput" class="avatar-file-input" type="file" accept="image/jpeg,image/png,image/webp" @change="onAvatarFile"><div class="avatar-actions"><AppButton type="button" variant="secondary" :disabled="auth.avatarBusy" @click="chooseAvatar"><Camera/>Đổi ảnh</AppButton><AppButton v-if="auth.currentUser?.avatarPath" type="button" variant="danger" :loading="auth.avatarBusy" @click="removeAvatar"><Trash2/>Xóa ảnh</AppButton></div></div></div></AppCard>
      <AppCard padding="lg" class="personal-card"><div class="section-title"><Palette/><div><span>GIAO DIỆN</span><h2>Màu sắc và cỡ chữ</h2></div></div><div class="choice-block"><b>Chế độ hiển thị</b><div class="segmented"><button type="button" :class="{active:preferences.theme==='system'}" @click="preferences.setTheme('system')">Theo hệ thống</button><button type="button" :class="{active:preferences.theme==='light'}" @click="preferences.setTheme('light')">Sáng</button><button type="button" :class="{active:preferences.theme==='dark'}" @click="preferences.setTheme('dark')">Tối</button></div></div><div class="choice-block"><div class="choice-label"><Type/><b>Cỡ chữ</b></div><div class="segmented"><button type="button" :class="{active:preferences.fontScale==='normal'}" @click="preferences.setFontScale('normal')">Mặc định</button><button type="button" :class="{active:preferences.fontScale==='large'}" @click="preferences.setFontScale('large')">Lớn</button></div></div></AppCard>
      <AppCard padding="lg" class="personal-card"><div class="section-title"><Sparkles/><div><span>TRỢ LÝ TRONG APP</span><h2>Cú Thông Thái</h2></div></div><div class="personal-options"><label class="personal-option"><span class="option-icon violet"><Eye/></span><span><b>Hiện Cú Thông Thái</b><small>Bạn có thể ẩn Cú; các cảnh báo quan trọng vẫn xuất hiện ở badge và card.</small></span><input v-model="preferences.owlEnabled" type="checkbox"></label><label class="personal-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon sky"><MousePointer2/></span><span><b>Chuyển động của Cú</b><small>Bật chuyển động mắt và nghiêng đầu nhẹ theo con trỏ.</small></span><input v-model="owlMotionModel" type="checkbox" :disabled="!preferences.owlEnabled"></label></div></AppCard>
      <AppCard v-if="isLearner" padding="lg" class="personal-card alerts-card"><div class="section-title"><BellRing/><div><span>CẢNH BÁO HỌC TẬP</span><h2>Luôn được bật</h2></div></div><p class="mandatory-note">Được hệ thống bật tự động để bạn không bỏ lỡ nhiệm vụ quan trọng.</p><div class="alert-list"><span><CheckCircle2/>Nhắc chưa đăng ký</span><span><CheckCircle2/>Nhắc có yêu cầu chỉnh sửa</span><span><CheckCircle2/>Nhắc trước buổi tự học</span><template v-if="isMonitor"><span class="monitor-alert"><CheckCircle2/>Lớp còn học sinh chưa đăng ký</span><span class="monitor-alert"><CheckCircle2/>Có học sinh cần chỉnh sửa</span><span class="monitor-alert"><CheckCircle2/>Gần đến buổi học nhưng còn đăng ký chưa hoàn tất</span></template></div></AppCard>
      <AppCard padding="lg" class="personal-card account-card"><div class="section-title"><UserRound/><div><span>TÀI KHOẢN</span><h2>Thông tin cá nhân</h2></div></div><dl class="identity-list"><div><dt>Họ tên</dt><dd>{{ auth.currentUser?.name }}</dd></div><div v-if="!isAdmin"><dt>Lớp</dt><dd>{{ classLabel||'—' }}</dd></div><div><dt>Vai trò</dt><dd>{{ roleLabel }}</dd></div><div><dt>Mã đăng nhập</dt><dd>{{ auth.currentUser?.code }}</dd></div></dl><form class="password-form" @submit.prevent="changePassword"><div class="choice-label"><KeyRound/><b>Đổi mật khẩu</b></div><div class="password-grid"><label>Mật khẩu hiện tại<input v-model="currentPassword" type="password" autocomplete="current-password"></label><label>Mật khẩu mới<input v-model="newPassword" type="password" autocomplete="new-password" minlength="8"></label></div><AppButton type="submit" variant="secondary" :loading="passwordBusy">Đổi mật khẩu</AppButton></form></AppCard>
    </section>
  </div>

  <div v-else class="page-stack settings-page"><nav v-if="isTeacher" class="teacher-settings-switch" aria-label="Chế độ cài đặt"><RouterLink :to="{path:'/settings',query:{view:'personal'}}">Tùy chọn cá nhân</RouterLink><RouterLink to="/settings" class="active">Cấu hình ứng dụng</RouterLink></nav><header><span>CẤU HÌNH ỨNG DỤNG</span><h1>Cài đặt</h1><p>Cấu hình lớp học, đăng ký, AI và trải nghiệm Cú Thông Thái.</p></header><AppTabs v-model="activeTab" :items="tabs" label="Nhóm cài đặt"/><InlineStatus :state="status" :message="statusMessage"/>
    <form @submit.prevent="save"><AppCard v-if="activeTab==='general'" padding="lg" class="settings-card"><div class="section-title"><Clock3/><div><span>THÔNG TIN LỚP</span><h2>Thiết lập chung</h2></div></div><div class="class-year-meta" aria-label="Thông tin cấu trúc lớp chỉ đọc"><div><span>Lớp</span><strong>{{ context.selectedClass?.code || context.selectedClass?.name || String(settings.className??'—') }}</strong><small>Do Quản trị hệ thống thiết lập</small></div><div><span>Năm học</span><strong>{{ context.selectedSchoolYear?.name || String(settings.schoolYear??'—') }}</strong><small>Do Quản trị hệ thống thiết lập</small></div></div><div class="field-grid"><label>Mốc deadline tự động<input v-model="registrationDeadlineTime" type="time" step="60"><small>Áp dụng cho chế độ “tối hôm trước từng buổi”.</small></label><label class="wide">Thông báo tuần<textarea v-model="announcement" rows="4"/></label></div><div class="periods"><span v-for="period in auth.legacyState?.periods??[]" :key="period.n"><b>Tiết {{ period.n }}</b><small>{{ period.start }} – {{ period.end }}</small></span></div></AppCard>
    <AppCard v-else-if="activeTab==='ai'" padding="lg" class="settings-card"><div class="section-title"><Bot/><div><span>TỰ ĐỘNG HÓA</span><h2>Duyệt đăng ký bằng AI</h2></div></div><label class="toggle"><input v-model="smartApprovalEnabled" type="checkbox"><span><b>Duyệt tự động bằng AI</b><small><strong>Bật:</strong> Groq kiểm tra đăng ký mới/gửi lại và học từ phản hồi GV.</small><small><strong>Tắt:</strong> Mọi đăng ký chuyển GV duyệt.</small></span></label><div class="threshold"><div><b>Ngưỡng AI được tự duyệt</b><small>AI dưới ngưỡng này luôn chuyển GV.</small></div><strong>{{ aiAutoApproveThreshold }}%</strong><input v-model.number="aiAutoApproveThreshold" type="range" min="80" max="99" step="1"></div><p class="explain">Đăng ký mới dùng ngưỡng <b>{{ aiAutoApproveThreshold }}%</b>. Khi học sinh sửa theo phản hồi GV, AI chỉ tự hành động khi độ chắc chắn đạt <b>{{ revisionThreshold }}%</b>; trường hợp không chắc chuyển giáo viên.</p><div class="memory"><span><small>Phản hồi đã ghi nhận</small><b>{{ Number(memory.totalFeedback??0) }}</b></span><span><small>AI duyệt → GV yêu cầu sửa</small><b>{{ Number(memory.revisionAfterAiApprove??0) }}</b></span><span><small>AI chuyển GV → GV duyệt</small><b>{{ Number(memory.approveAfterAiManual??0) }}</b></span><span><small>AI yêu cầu sửa → GV duyệt</small><b>{{ Number(memory.approveAfterAiRevision??0) }}</b></span></div></AppCard>
    <AppCard v-else padding="lg" class="settings-card owl-settings"><div class="section-title"><Sparkles/><div><span>TRỢ LÝ TRONG APP</span><h2>Cú Thông Thái</h2></div></div><p class="owl-intro">Chọn cách Cú xuất hiện và tương tác. Các tùy chọn này áp dụng ngay trên thiết bị hiện tại.</p><div class="owl-options">
    <label class="owl-option"><span class="option-icon violet"><Eye/></span><span><b>Hiện Cú Thông Thái</b><small>Ẩn hoàn toàn Cú nếu bạn muốn giao diện tối giản hơn.</small></span><input v-model="preferences.owlEnabled" type="checkbox"></label>
    <label class="owl-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon sky"><MousePointer2/></span><span><b>Mắt theo con trỏ</b><small>Đồng tử di chuyển nhẹ theo vị trí chuột.</small></span><input v-model="preferences.owlFollowPointer" type="checkbox" :disabled="!preferences.owlEnabled"></label>
    <label class="owl-option" :class="{disabled:!preferences.owlEnabled||!preferences.owlFollowPointer}"><span class="option-icon mint"><RotateCw/></span><span><b>Nghiêng đầu theo con trỏ</b><small>Đầu nghiêng tối đa ±5° để chuyển động tự nhiên.</small></span><input v-model="preferences.owlHeadTilt" type="checkbox" :disabled="!preferences.owlEnabled||!preferences.owlFollowPointer"></label>
    <label class="owl-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon coral"><BellRing/></span><span><b>Tự mở cảnh báo cần chú ý</b><small>Tự bật lời nhắc khi còn đăng ký hoặc thông báo cần xử lý.</small></span><input v-model="preferences.owlAutoOpenUrgent" type="checkbox" :disabled="!preferences.owlEnabled"></label>
    <label class="owl-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon sun"><Quote/></span><span><b>Luân phiên danh ngôn</b><small>Cho Cú hiển thị danh ngôn sau các lời nhắc theo ngữ cảnh.</small></span><input v-model="preferences.owlQuotesEnabled" type="checkbox" :disabled="!preferences.owlEnabled"></label>
    </div><div class="instant-note">✓ Cài đặt Cú được lưu tự động trên trình duyệt này.</div></AppCard>
    <div v-if="activeTab!=='owl'" class="save-bar"><span>Mọi thay đổi chỉ được lưu khi bấm nút bên cạnh.</span><AppButton type="submit" :loading="saving"><Save/>Lưu cài đặt</AppButton></div></form>
  </div>
  <AvatarEditor v-if="avatarEditorFile" :file="avatarEditorFile" @cancel="closeAvatarEditor" @save="saveAvatar"/>
</template>

<style scoped>
